// Fails the build if public/THIRD-PARTY-NOTICES.txt no longer matches what we
// actually ship, so the attribution that goes out with an AGPL release stays true.
// Both halves are generated by hand, so without this they drift silently: when this
// check was written Part 1 named pdfjs-dist 4.10.38 while the app shipped 6.4.299
// and omitted two Tauri plugins, and Part 4 was missing 64 crates, 23 of them under
// a licence (ISC) that appeared nowhere in the file. Runs before `npm run build`.
//
// `node scripts/check-third-party-notices.mjs --fix` updates Part 1 version numbers.
// Nothing else is written for you:
//   - a package missing from Part 1 needs putting under the right licence block,
//     which is a judgement call;
//   - Part 4 comes from cargo-about, so regenerate it (see CONTRIBUTING.md) rather
//     than editing versions by hand.
// Part 4 is checked against src-tauri/Cargo.lock, which needs no Rust toolchain. Only
// one direction is meaningful: every crate listed must be locked at that version.
// The reverse is not, because Part 4 covers the Windows target while Cargo.lock
// covers every platform.
import { readFileSync, writeFileSync } from 'node:fs';

const FILE = 'public/THIRD-PARTY-NOTICES.txt';
const PART4 = 'The following Rust crates are compiled into the Windows desktop app';
const fix = process.argv.includes('--fix');

const { dependencies } = JSON.parse(readFileSync('package.json', 'utf8'));
let notices = readFileSync(FILE, 'utf8');
const problems = [];

// ---- Part 1: npm packages, listed one per line as " - name@version" ----------
const part1 = notices.slice(0, notices.indexOf(PART4));
const listed = new Map([...part1.matchAll(/^ - (@?[^@\s]+(?:\/[^@\s]+)?)@([0-9]\S*)$/gm)].map((m) => [m[1], m[2]]));

const installed = (name) => {
  try {
    return JSON.parse(readFileSync(`node_modules/${name}/package.json`, 'utf8')).version;
  } catch {
    return null; // not installed: `npm ci` has not run, so there is nothing to compare against
  }
};

const stale = [];
for (const name of Object.keys(dependencies)) {
  const version = installed(name);
  if (!version) continue;
  if (!listed.has(name)) problems.push(`${name}@${version} is shipped but missing from Part 1`);
  else if (listed.get(name) !== version) stale.push({ name, version, was: listed.get(name) });
}

if (fix && stale.length) {
  for (const { name, version, was } of stale) notices = notices.replace(`\n - ${name}@${was}\n`, `\n - ${name}@${version}\n`);
  writeFileSync(FILE, notices);
  console.log(`${FILE}: updated ${stale.length} version${stale.length === 1 ? '' : 's'} in Part 1`);
  stale.length = 0;
}
for (const { name, version, was } of stale) problems.push(`Part 1 lists ${name} ${was}, but ${version} is installed`);

// ---- Part 4: Rust crates, listed as " - name version (repository)" -----------
const lock = readFileSync('src-tauri/Cargo.lock', 'utf8');
const locked = new Set([...lock.matchAll(/\[\[package\]\]\nname = "([^"]+)"\nversion = "([^"]+)"/g)].map((m) => `${m[1]} ${m[2]}`));
const part4 = notices.slice(notices.indexOf(PART4));
for (const [, name, version] of part4.matchAll(/^ - (\S+) (\d[^\s(]*) \(/gm)) {
  if (!locked.has(`${name} ${version}`)) problems.push(`Part 4 lists ${name} ${version}, which is not in src-tauri/Cargo.lock`);
}

if (problems.length) {
  for (const p of problems) console.error(`${FILE}: ${p}`);
  console.error('See CONTRIBUTING.md (Dependencies) for how to regenerate each part.');
  process.exit(1);
}
